window.AUTH=window.AUTH||{};window.AUTH["18-1501"]={"d":"18-1501","id":"2019/18-1501","n":"Liu v. Securities and Exchange Commission","briefs":[{"k":"petitioner","label":"Brief of petitioners Charles C. Liu, et al.","date":"2019-12-16","url":"https://www.supremecourt.gov/DocketPDF/18/18-1501/125720/20191216162743633_18-1501ts.pdf","side":"pet","n":122},{"k":"respondent","label":"Brief of respondent Securities and Exchange Commission","date":"2020-01-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-1501/128801/20200115181538414_18-1501bsUnitedStates.pdf","side":"res","n":77},{"k":"reply","label":"Reply of petitioners Charles C. Liu, et al.","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-1501/133092/20200214140944857_18-1501rb.pdf","side":"pet","n":93}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US1PP_web.pdf#page=81","tr":true,"items":[{"t":"case","label":"Aaron v. SEC","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"op":1,"sum":"The Court held that plain language and the legislative history of the statutes required the SEC to establish defendant’s intent to “deceive, manipulate, or defraud” for violations of Section 10(b) and the part of Section 17(a) that specifically refers to the use of a device, scheme, or artifice with intent to defraud.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"39","1":"13"}},{"t":"case","label":"Beals v. Washington Int’l, Inc.","cite":"386 A.2d 1156","y":1978,"court":"Del. Ch.","url":"https://www.courtlistener.com/c/A.2d/386/1156/","by":{"0":"24"}},{"t":"case","label":"Brady v. Daly","cite":"175 U.S. 148","y":1899,"id":"scdb/1899-011","sc":1,"sum":"Section 4966 of the Revised Statutes, enacting that “any person publicly performing or representing any dramatic composition for which a copyright has been obtained, without the consent of the proprietor thereof, or his heirs or assigns, shall be liable for damages, therefor, such damages in all cases to be assessed at such sum, not less than one hundred dollars for the first, and fifty dollars for every subsequent …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"38, 39, 40","2":"13"}},{"t":"case","label":"Craig v. Hukill","cite":"16 S.E. 363","y":1892,"court":"W. Va.","url":"https://www.courtlistener.com/c/S.E./16/363/","by":{"0":"21"}},{"t":"case","label":"Cross v. McClenahan","cite":"54 Md. 21","y":1880,"url":"https://www.courtlistener.com/c/Md./54/21/","by":{"0":"21"}},{"t":"case","label":"Dairy Queen, Inc. v. Wood","cite":"369 U.S. 469","y":1962,"id":"1961/244","sc":1,"sum":"The District Judge erred in refusing petitioner's.demand for a trial by jury of the factual issues related to the question whether there had been a breach of contract or a trademark infringement, and the Court of Appeals should have corrected that error by granting the petition for mandamus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 30"}},{"t":"case","label":"DHS v. MacLean","cite":"135 S. Ct. 913","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/913/","sc":1,"by":{"0":"18"}},{"t":"case","label":"Digital Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Douglas v. Independent Living Ctr. of S. California, Inc.","cite":"565 U.S. 606","y":2012,"id":"2011/09-958","sc":1,"op":1,"sum":"A case which the Court remanded to the Ninth Circuit regarding whether or not federal law preempts state reductions in Medicaid payments.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Ellis v. Davis","cite":"109 U.S. 485","y":1883,"id":"scdb/1883-068","sc":1,"sum":"Conflict of Laws — Constitutional Law — Jurisdiction—Louisiana—Practice— Probate of Wills — Wills.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"0":"37-38"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"35, 38"}},{"t":"case","label":"FTC v. AMG Capital Mgmt., LLC","cite":"910 F.3d 417","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/910/417/","by":{"0":"22"}},{"t":"case","label":"FTC v. Credit Bureau Ctr., LLC","cite":"937 F.3d 764","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/764/","by":{"0":"34"}},{"t":"case","label":"FTC v. Leshin","cite":"719 F.3d 1227","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/719/1227/","by":{"0":"32"}},{"t":"case","label":"Gordon v. Lowell","cite":"21 Me. 251","y":1842,"url":"https://www.courtlistener.com/c/Me./21/251/","by":{"0":"21"}},{"t":"case","label":"Granfinanciera, S.A. v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"sum":"The Court held that the Seventh Amendment protected the right to a trial by jury in all cases in which a legal right, as opposed to an equitable right, was at issue.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Great-West Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"op":4,"ar":5,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"0":"2, 17, 26, 27, 30, 31, 32, 33","1":"31","2":"4, 6, 7, 15"}},{"t":"case","label":"Grupo Mexicano de Desarrollo, S.A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"op":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"0":"26, 27, 28","1":"29"}},{"t":"case","label":"Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Found., Inc.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","1":"34","2":"3"}},{"t":"case","label":"Helvering v. Hallock","cite":"309 U.S. 106","y":1940,"id":"scdb/1939-097","sc":1,"sum":"1. Decedent in his lifetime created a trust providing that the income from the trust property should be paid to his wife during her lifetime, that upon his death, if she survived him, the corpus of the trust should go to her or to other named beneficiaries, but that upon her death, if he survived, the property should revert to himself. The wife survived. Held, that the value of the remainder interest clearly …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","2":"15"}},{"t":"case","label":"Huntington v. Attrill","cite":"146 U.S. 657","y":1892,"id":"scdb/1892-054","sc":1,"sum":"A bill in equity in one State to set aside a conveyance of property made in fraud of creditors, aiyl to charge it' with' the payment ofa judgment since recovered by the plaintiff against the debtor in another State upon his liability as aji officer in a corporation under a statute of that State, set forth the judgment and the cause of action on which it was recovered; and' also asserted, independently of the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26","1":"33"}},{"t":"case","label":"Kokesh v. SEC","cite":"137 S. Ct. 1635","y":2017,"id":"2016/16-529","sc":1,"op":7,"ar":8,"sum":"The Court held that Securities and Exchange Commission (SEC) disgorgement functions as a penalty, and therefore is subject to the five-year statute of limitations.Commission seeking “disgorgement,” or payment, of illegally obtained funds.","sumSrc":"Oyez","by":{"0":"1, 2, 3, 4, 5, 6, 7, 11, 12, 13, 16, 19, 22, 23, 24, 25, 26, 27, 30, 32, 35, 40, 42, 2, 16, 17, 31","1":"32, 33, 34, 43","2":"2, 3, 4, 8, 11, 13, 19, 20"}},{"t":"case","label":"Leman v. Krentler-Arnold Hinge Last Co.","cite":"284 U.S. 448","y":1932,"id":"scdb/1931-129","sc":1,"by":{"0":"30","2":"9"}},{"t":"case","label":"Limelight Networks, Inc. v. Akamai Techs., Inc.","cite":"572 U.S. 915","y":2014,"id":"2013/12-786","sc":1,"sum":"The Court held that a party is not liable for patent infringement under 35 U.S.C. § 271(b) unless the party has also violated Section 217(a)o or any other statutory provision.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Louisiana Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Massachusetts Mut. Life Ins. Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"op":1,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","2":"17, 18"}},{"t":"case","label":"Meghrig v. KFC W., Inc.","cite":"516 U.S. 479","y":1996,"id":"1995/95-83","sc":1,"sum":"In a unanimous opinion delivered by Justice Sandra Day O'Connor the Court held that section 6972 does not authorize a private cause of action to recover the prior cost of cleaning up toxic waste that does not, at the time of suit, continue to pose an endangerment to health or the environment.","sumSrc":"Oyez","by":{"0":"16, 34","2":"12"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"op":5,"sum":"Interpreting the term “appropriate equitable relief ”.","sumSrc":"opinion","by":{"0":"16, 17, 26, 34","1":"30, 31","2":"6, 7, 15"}},{"t":"case","label":"Miller v. Gammie","cite":"335 F.3d 889","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/335/889/","by":{"0":"12"}},{"t":"case","label":"Mitchell v. Robert De Mario Jewelry, Inc.","cite":"361 U.S. 288","y":1960,"id":"1959/39","sc":1,"op":2,"sum":"In an action by the Secretary of Labor under § 17 of the Fair Labor Standards Act of 1938, as amended, to restrain violations of § 15 (a) (3), a district court has jurisdiction to order an employer to reimburse employees unlawfully discharged or otherwise discriminated against for wages lost because of that discharge or discrimination.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Montanile v. Board of Trs. of Nat’l Elevator Indus. Health Benefit Plan","cite":"136 S. Ct. 651","y":2016,"id":"2015/14-723","sc":1,"op":1,"sum":"The Court determined that the Employee Retirement Income Security Act of 1974 does not allow for a suit to recover reimbursement of an asset that has been fully disbursed on non-traceable items such as services.","sumSrc":"Oyez","by":{"0":"31, 32","2":"6, 10"}},{"t":"case","label":"Northwest Airlines, Inc. v. Transport Workers Union of Am.","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"sum":"Petitioner has neither a federal statutory nor a federal common-law right to contribution from respondent unions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Osborn v. Griffin","cite":"865 F.3d 417","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/865/417/","by":{"0":"22-23, 27"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 39"}},{"t":"case","label":"Pension Benefit Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Porter v. Warner Holding Co.","cite":"328 U.S. 395","y":1946,"id":"scdb/1945-032","sc":1,"op":2,"ar":1,"sum":"1. In an.enforcement proceeding under § 205 (a) of the Emergency Price Control Act of 1942, a Federal District Court has power to order restitution of rents collected by a landlord in excess of maximums established by regulations issued under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 31, 34","1":"8, 11, 34, 35","2":"4, 10, 10"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18"}},{"t":"case","label":"Root v. Lake Shore & M.S. Ry. Co.","cite":"105 U.S. 189","y":1882,"id":"scdb/1881-134","sc":1,"op":8,"by":{"0":"29, 30","1":"9","2":"9, 10"}},{"t":"case","label":"Robers v. United States","cite":"572 U.S. 639","y":2014,"id":"2013/12-9012","sc":1,"sum":"The Court held that, under the Mandatory Victims Restitution Act, individuals accused of property crime must pay “an amount equal to...the value of the property,” minus “the value...of any part of the property that is returned\" in retribution.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Robinson v. Robinson","cite":"53 N.E. 854","y":1899,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./53/854/","sum":"Describing an “action of account” under an English statute as “like the accountability of a trustee,” and adding that “[t]he relation between the parties is fiduciary”.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"2019 WL 6703563","y":2019,"court":"U.S. Dec. 10","by":{"0":"19"}},{"t":"case","label":"Saad v. SEC","cite":"873 F.3d 297","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/873/297/","by":{"0":"22"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Sandoz Inc. v. Amgen Inc.","cite":"137 S. Ct. 1664","y":2017,"id":"2016/15-1039","sc":1,"sum":"The Court determined that the Biologics Price Competition and Innovation Act of 2009 allows for commercial notice of a “biosimilar product” to be effective if given prior to approval by the Food and Drug Administration (FDA), but that the Act’s notice requirement is not enforceable with an injunction.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"SEC v. Banner Fund Int’l","cite":"211 F.3d 602","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/211/602/","by":{"0":"32"}},{"t":"case","label":"SEC v. Clark","cite":"915 F.2d 439","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/915/439/","op":2,"by":{"0":"24"}},{"t":"case","label":"SEC v. Commonwealth Chem. Sec., Inc.","cite":"574 F.2d 90","y":1978,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/574/90/","op":1,"sum":"Explaining that, when a court awards “[d]isgorgement of profts in an action brought by the SEC,” it is “exercising the chancellor's discretion to prevent unjust enrichment”.","sumSrc":"opinion","by":{"0":"7","1":"12, 37"}},{"t":"case","label":"SEC v. Contorinis","cite":"743 F.3d 296","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/743/296/","op":2,"sum":"Holding that a defendant could be forced to disgorge not only what he “personally enjoyed from his exploitation of inside information, but also the profts of such exploitation that he channeled to friends, family, or clients”.","sumSrc":"opinion","by":{"0":"24"}},{"t":"case","label":"SEC v. Fischbach Corp.","cite":"133 F.3d 170","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/133/170/","by":{"0":"23","1":"12, 38"}},{"t":"case","label":"SEC v. Gentile","cite":"939 F.3d 549","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/939/549/","by":{"0":"33"}},{"t":"case","label":"SEC v. Huffman","cite":"996 F.2d 800","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/996/800/","by":{"0":"7, 31"}},{"t":"case","label":"SEC v. Jerry T. O’Brien, Inc.","cite":"467 U.S. 735","y":1984,"id":"1983/83-751","sc":1,"sum":"The SEC is not required to notify the \"targets\" of nonpublic investigations into possible violations of the securities laws when the SEC issues subpoenas to third parties. The SEC has discretion to determine when such notice would be appropriate and when it would not.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"SEC v. Materia","cite":"745 F.2d 197","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/745/197/","by":{"0":"37"}},{"t":"case","label":"SEC v. Platforms Wireless Int’l Corp.","cite":"617 F.3d 1072","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/617/1072/","by":{"0":"32"}},{"t":"case","label":"SEC v. Shapiro","cite":"494 F.2d 1301","y":1974,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/494/1301/","op":2,"by":{"0":"32"}},{"t":"case","label":"SEC v. Texas Gulf Sulphur Co.: 312 F. Supp. 77 (S.D.N.Y. 1970), aff ’d in part, rev’d and remanded in part","cite":"446 F.2d 1301","y":1971,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/446/1301/","op":5,"ar":1,"by":{"0":"6, 23, 27, 39","1":"6, 11, 12","2":"13, 14, 17"}},{"t":"case","label":"SEC v. Warde","cite":"151 F.3d 42","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/151/42/","by":{"0":"24"}},{"t":"case","label":"SEC v. Whittemore","cite":"659 F.3d 1","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/659/1/","op":1,"by":{"0":"32"}},{"t":"case","label":"Sereboff v. Mid Atl. Med. Servs., Inc.","cite":"547 U.S. 356","y":2006,"id":"2005/05-260","sc":1,"sum":"In Barnes, an attorney's promise to pay two other attorneys a portion of the money he collected from a case that had yet to be decided was held legally binding. Roberts wrote that equity had once required a contract to specify an existing fund from which money would be paid (which could not have happened in this case), but that after Barnes this was no longer the case.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Stark v. Wickard","cite":"321 U.S. 288","y":1944,"id":"scdb/1943-091","sc":1,"sum":"that the producers had standing to sue. Pp. 289, 305.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Stevens v. Cady","cite":"23 F. Cas. 8","y":1854,"court":"C.C.D.R.I.","url":"https://www.courtlistener.com/c/F.%20Cas./23/8/","by":{"0":"21"}},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. ScientificAtlanta, Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"sum":"The Court held that, under Central Bank and Section 10(b), securities fraud plaintiffs cannot sue \"aiders and abettors\" like Scientific-Atlanta. The Court noted Congress' subsequent failure to create a right of private action against aiders and abettors in the Private Securities Litigation Reform Act for support of its position that no such right should be allowed in the present case.","sumSrc":"Oyez","by":{"0":"39","1":"43"}},{"t":"case","label":"Tull v. United States","cite":"481 U.S. 412","y":1987,"id":"1986/85-1259","sc":1,"op":3,"sum":"The Clean Water Act (Act) authorizes injunctive relief against violators (33 U. S. C. § 1319(b)) and subjects them to a civil penalty not to exceed $10,000 per day (§ 1319(d)). After denying petitioner's timely demand for a jury trial in the Government's suit for relief under §§ 1319(b) and 1319(d), the District Court imposed civil penalties and granted injunctive relief against petitioner. The Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 21, 27, 31","1":"5, 7, 9, 35","2":"4, 10, 11"}},{"t":"case","label":"United States v. Bernard","cite":"202 F. 728","y":1913,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F./202/728/","by":{"0":"21"}},{"t":"case","label":"United States v. Bitter Root Dev. Co.","cite":"200 U.S. 451","y":1906,"id":"scdb/1905-084","sc":1,"sum":"Notwithstanding averments in the bill of fraud, conspiracy and violation of trust, if the action is really one of trespass or trover to recover damages for wrongful cutting and conversion of timber from complainant’s lands, and there is no question of defendant’s financial responsibility, and the recovery of a money judgment and not of specific property is sought, complainant’s remedy at law is adequate and equity …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Wallace v. Cutten","cite":"298 U.S. 229","y":1936,"id":"scdb/1935-120","sc":1,"op":1,"ar":1,"sum":"Section 6 (b) of the Gxrain Futures Act, which provides that if the Secretary of Agriculture has reason to believe that any person \"is violating\" the Act or the regulations thereunder, or \"is attempting\" to manipulate the market price of grain in violation of the Act, he may require such person to show cause why he should not be suspended from trading in Contract Markets, cannot be construed as authorizing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Weinberger v. Romero-Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 95-217","url":"https://www.govinfo.gov/link/statute/91/1566","by":{"0":"18"}},{"t":"law","label":"Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"0":"1, 3, 13, 17, 18, 41","2":"19"}},{"t":"usc","label":"7 U.S.C. § 13a-1","url":"https://www.law.cornell.edu/uscode/text/7/13a-1","subs":["(d)(3)(B)"],"stext":{"head":"§13a–1. Enjoining or restraining violations","paras":[[0,"(a) Action to enjoin or restrain violations"],[0,"Whenever it shall appear to the Commission that any registered entity or other person has engaged, is engaging, or is about to engage in any act or practice constituting a violation of any provision of this chapter or any rule, regulation, or order thereunder, or is restraining trading in any commodity for future delivery or any swap, the Commission may bring an action in the proper district court of the United States or the proper United States court of any territory or other place subject to the jurisdiction of the United States, to enjoin such act or practice, or to enforce compliance with this chapter, or any rule, regulation or order thereunder, and said courts shall have jurisdiction to entertain such actions: Provided, That no restraining order (other than a restraining order which prohibits any person from destroying, altering or disposing of, or refusing to permit authorized representatives of the Commission to inspect, when and as requested, any books and records or other documents or which prohibits any person from withdrawing, transferring, removing, dissipating, or disposing of any funds, assets, or other property, and other than an order appointing a temporary receiver to administer such restraining order and to perform such other duties as the court may consider appropriate) or injunction for violation of the provisions of this chapter shall be issued ex parte by said court."],[0,"(b) Injunction or restraining order"],[0,"Upon a proper showing, a permanent or temporary injunction or restraining order shall be granted without bond."],[0,"(c) Writs or other orders"],[0,"Upon application of the Commission, the district courts of the United States and the United States courts of any territory or other place subject to the jurisdiction of the United States shall also have jurisdiction to issue writs of mandamus, or orders affording like relief, commanding any person to comply with the provisions of this chapter or any rule, regulation, or order of the Commission thereunder, including the requirement that such person take such action as is necessary to remove the danger of violation of this chapter or any such rule, regulation, or order: Provided, That no such writ of mandamus, or order affording like relief, shall be issued ex parte."],[0,"(d) Civil penalties"],[0,"(1) In general.—In any action brought under this section, the Commission may seek and the court shall have jurisdiction to impose, on a proper showing, on any person found in the action to have committed any violation—"],[1,"(A) a civil penalty in the amount of not more than the greater of $100,000 or triple the monetary gain to the person for each violation; or"],[1,"(B) in any case of manipulation or attempted manipulation in violation of section 9, 15, 13b, or 13(a)(2) of this title, a civil penalty in the amount of not more than the greater of $1,000,000 or triple the monetary gain to the person for each violation."],[0,"(2) If a person on whom such a penalty is imposed fails to pay the penalty within the time prescribed in the court's order, the Commission may refer the matter to the Attorney General who shall recover the penalty by action in the appropriate United States district court."],[0,"(3) Equitable remedies.—In any action brought under this section, the Commission may seek, and the court may impose, on a proper showing, on any person found in the action to have committed any violation, equitable remedies including—"],[1,"(A) restitution to persons who have sustained losses proximately caused by such violation (in the amount of such losses); and"],[1,"(B) disgorgement of gains received in connection with such violation."],[0,"(e) Venue and process"],[0,"Any action under this section may be brought in the district wherein the defendant is found or is an inhabitant or transacts business or in the district where the act or practice occurred, is occurring, or is about to occur, and process in such cases may be served in any district in which the defendant is an inhabitant or wherever the defendant may be found."],[0,"(f) Action by Attorney General"],[0,"In lieu of bringing actions itself pursuant to this section, the Commission may request the Attorney General to bring the action."],[0,"(g) Notice to Attorney General of action brought by Commission"],[0,"Where the Commission elects to bring the action, it shall inform the Attorney General of such suit and advise him of subsequent developments."],[0,"(h) Notice of investigations and enforcement actions"],[0,"The Commission shall provide the Securities and Exchange Commission with notice of the commencement of any proceeding and a copy of any order entered by the Commission against any futures commission merchant or introducing broker registered pursuant to section 6f(a)(2) of this title, any floor broker or floor trader exempt from registration pursuant to section 6f(a)(3) of this title, any associated person exempt from registration pursuant to section 6k(6) of this title, or any board of trade designated as a contract market pursuant to section 7b–1 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/13a-1?type=usc&year=mostrecent&link-type=html"},"head":"§13a–1. Enjoining or restraining violations","tname":"Agriculture","by":{"0":"17, 18","1":"9"}},{"t":"usc","label":"12 U.S.C. § 5565","url":"https://www.law.cornell.edu/uscode/text/12/5565","subs":["(a)(1)","(a)(2)(D)"],"by":{"0":"18, 18"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"26","1":"30","2":"6, 7"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"34"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"0":"39","1":"17","2":"19"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","stext":{"head":"§77a. Short title","paras":[[0,"This subchapter may be cited as the \"Securities Act of 1933\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77a. Short title","tname":"Commerce and Trade","by":{"0":"3, 9","1":"2","2":"12"}},{"t":"usc","label":"15 U.S.C. § 77h-1","url":"https://www.law.cornell.edu/uscode/text/15/77h-1","subs":["(a)","(e)","(g)(1)","(g)(2)","(g)(2)(C)","(g)"],"stext":{"head":"§77h–1. Cease-and-desist proceedings","paras":[[0,"(a) Authority of Commission"],[0,"If the Commission finds, after notice and opportunity for hearing, that any person is violating, has violated, or is about to violate any provision of this subchapter, or any rule or regulation thereunder, the Commission may publish its findings and enter an order requiring such person, and any other person that is, was, or would be a cause of the violation, due to an act or omission the person knew or should have known would contribute to such violation, to cease and desist from committing or causing such violation and any future violation of the same provision, rule, or regulation. Such order may, in addition to requiring a person to cease and desist from committing or causing a violation, require such person to comply, or to take steps to effect compliance, with such provision, rule, or regulation, upon such terms and conditions and within such time as the Commission may specify in such order. Any such order may, as the Commission deems appropriate, require future compliance or steps to effect future compliance, either permanently or for such period of time as the Commission may specify, with such provision, rule, or regulation with respect to any security, any issuer, or any other person."],[0,"(b) Hearing"],[0,"The notice instituting proceedings pursuant to subsection (a) shall fix a hearing date not earlier than 30 days nor later than 60 days after service of the notice unless an earlier or a later date is set by the Commission with the consent of any respondent so served."],[0,"(c) Temporary order"],[0,"(1) In general"],[1,"Whenever the Commission determines that the alleged violation or threatened violation specified in the notice instituting proceedings pursuant to subsection (a), or the continuation thereof, is likely to result in significant dissipation or conversion of assets, significant harm to investors, or substantial harm to the public interest, including, but not limited to, losses to the Securities Investor Protection Corporation, prior to the completion of the proceedings, the Commission may enter a temporary order requiring the respondent to cease and desist from the violation or threatened violation and to take such action to prevent the violation or threatened violation and to prevent dissipation or conversion of assets, significant harm to investors, or substantial harm to the public interest as the Commission deems appropriate pending completion of such proceeding. Such an order shall be entered only after notice and opportunity for a hearing, unless the Commission determines that notice and hearing prior to entry would be impracticable or contrary to the public interest. A temporary order shall become effective upon service upon the respondent and, unless set aside, limited, or suspended by the Commission or a court of competent jurisdiction, shall remain effective and enforceable pending the completion of the proceedings."],[0,"(2) Applicability"],[1,"This subsection shall apply only to a respondent that acts, or, at the time of the alleged misconduct acted, as a broker, dealer, investment adviser, investment company, municipal securities dealer, government securities broker, government securities dealer, or transfer agent, or is, or was at the time of the alleged misconduct, an associated person of, or a person seeking to become associated with, any of the foregoing."],[0,"(d) Review of temporary orders"],[0,"(1) Commission review"],[1,"At any time after the respondent has been served with a temporary cease-and-desist order pursuant to subsection (c), the respondent may apply to the Commission to have the order set aside, limited, or suspended. If the respondent has been served with a temporary cease-and-desist order entered without a prior Commission hearing, the respondent may, within 10 days after the date on which the order was served, request a hearing on such application and the Commission shall hold a hearing and render a decision on such application at the earliest possible time."],[0,"(2) Judicial review"],[1,"Within—"],[2,"(A) 10 days after the date the respondent was served with a temporary cease-and-desist order entered with a prior Commission hearing, or"],[2,"(B) 10 days after the Commission renders a decision on an application and hearing under paragraph (1), with respect to any temporary cease-and-desist order entered without a prior Commission hearing,"],[1,"the respondent may apply to the United States district court for the district in which the respondent resides or has its principal place of business, or for the District of Columbia, for an order setting aside, limiting, or suspending the effectiveness or enforcement of the order, and the court shall have jurisdiction to enter such an order. A respondent served with a temporary cease-and-desist order entered without a prior Commission hearing may not apply to the court except after hearing and decision by the Commission on the respondent's application under paragraph (1) of this subsection."],[0,"(3) No automatic stay of temporary order"],[1,"The commencement of proceedings under paragraph (2) of this subsection shall not, unless specifically ordered by the court, operate as a stay of the Commission's order."],[0,"(4) Exclusive review"],[1,"Section 77i(a) of this title shall not apply to a temporary order entered pursuant to this section."],[0,"(e) Authority to enter order requiring accounting and disgorgement"],[0,"In any cease-and-desist proceeding under subsection (a), the Commission may enter an order requiring accounting and disgorgement, including reasonable interest. The Commission is authorized to adopt rules, regulations, and orders concerning payments to investors, rates of interest, periods of accrual, and such other matters as it deems appropriate to implement this subsection."],[0,"(f) Authority of the Commission to prohibit persons from serving as officers or directors"],[0,"In any cease-and-desist proceeding under subsection (a), the Commission may issue an order to prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who has violated section 77q(a)(1) of this title or the rules or regulations thereunder, from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title, or that is required to file reports pursuant to section 78o(d) of this title, if the conduct of that person demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(g) Authority to impose money penalties"],[0,"(1) Grounds"],[1,"In any cease-and-desist proceeding under subsection (a), the Commission may impose a civil penalty on a person if the Commission finds, on the record, after notice and opportunity for hearing, that—"],[2,"(A) such person—"],[3,"(i) is violating or has violated any provision of this subchapter, or any rule or regulation issued under this subchapter; or"],[3,"(ii) is or was a cause of the violation of any provision of this subchapter, or any rule or regulation thereunder; and"],[2,"(B) such penalty is in the public interest."],[0,"(2) Maximum amount of penalty"],[0,"(A) First tier"],[2,"The maximum amount of a penalty for each act or omission described in paragraph (1) shall be $7,500 for a natural person or $75,000 for any other person."],[0,"(B) Second tier"],[2,"Notwithstanding subparagraph (A), the maximum amount of penalty for each such act or omission shall be $75,000 for a natural person or $375,000 for any other person, if the act or omission described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[0,"(C) Third tier"],[2,"Notwithstanding subparagraphs (A) and (B), the maximum amount of penalty for each such act or omission shall be $150,000 for a natural person or $725,000 for any other person, if—"],[3,"(i) the act or omission described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement; and"],[3,"(ii) such act or omission directly or indirectly resulted in—"],[4,"(I) substantial losses or created a significant risk of substantial losses to other persons; or"],[4,"(II) substantial pecuniary gain to the person who committed the act or omission."],[0,"(3) Evidence concerning ability to pay"],[1,"In any proceeding in which the Commission may impose a penalty under this section, a respondent may present evidence of the ability of the respondent to pay such penalty. The Commission may, in its discretion, consider such evidence in determining whether such penalty is in the public interest. Such evidence may relate to the extent of the ability of the respondent to continue in business and the collectability of a penalty, taking into account any other claims of the United States or third parties upon the assets of the respondent and the amount of the assets of the respondent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77h-1?type=usc&year=mostrecent&link-type=html"},"head":"§77h–1. Cease-and-desist proceedings","tname":"Commerce and Trade","by":{"0":"28, 4, 5, 17, 4, 5, 5, 5, 17, 40-41","2":"12, 19, 19"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(2)","(a)(1)"],"stext":{"head":"§77q. Fraudulent interstate transactions","paras":[[0,"(a) Use of interstate commerce for purpose of fraud or deceit"],[0,"It shall be unlawful for any person in the offer or sale of any securities (including security-based swaps) or any security-based swap agreement (as defined in section 78c(a)(78) 1 of this title) by the use of any means or instruments of transportation or communication in interstate commerce or by use of the mails, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud, or"],[1,"(2) to obtain money or property by means of any untrue statement of a material fact or any omission to state a material fact necessary in order to make the statements made, in light of the circumstances under which they were made, not misleading; or"],[1,"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser."],[0,"(b) Use of interstate commerce for purpose of offering for sale"],[0,"It shall be unlawful for any person, by the use of any means or instruments of transportation or communication in interstate commerce or by the use of the mails, to publish, give publicity to, or circulate any notice, circular, advertisement, newspaper, article, letter, investment service, or communication which, though not purporting to offer a security for sale, describes such security for a consideration received or to be received, directly or indirectly, from an issuer, underwriter, or dealer, without fully disclosing the receipt, whether past or prospective, of such consideration and the amount thereof."],[0,"(c) Exemptions of section 77c not applicable to this section"],[0,"The exemptions provided in section 77c of this title shall not apply to the provisions of this section."],[0,"(d) Authority with respect to security-based swap agreements"],[0,"The authority of the Commission under this section with respect to security-based swap agreements (as defined in section 78c(a)(78) of this title) shall be subject to the restrictions and limitations of section 77b–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77q?type=usc&year=mostrecent&link-type=html"},"head":"§77q. Fraudulent interstate transactions","tname":"Commerce and Trade","by":{"0":"9, 9","1":"3, 3, 4"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","subs":["(b)","(b)(1)","(d)","(d)(2)(A)","(d)(2)(C)","(d)(3)(C)","(e)","(g)"],"stext":{"head":"§77t. Injunctions and prosecution of offenses","paras":[[0,"(a) Investigation of violations"],[0,"Whenever it shall appear to the Commission, either upon complaint or otherwise, that the provisions of this subchapter, or of any rule or regulation prescribed under authority thereof, have been or are about to be violated, it may, in its discretion, either require or permit such person to file with it a statement in writing, under oath, or otherwise, as to all the facts and circumstances concerning the subject matter which it believes to be in the public interest to investigate, and may investigate such facts."],[0,"(b) Action for injunction or criminal prosecution in district court"],[0,"Whenever it shall appear to the Commission that any person is engaged or about to engage in any acts or practices which constitute or will constitute a violation of the provisions of this subchapter, or of any rule or regulation prescribed under authority thereof, the Commission may, in its discretion, bring an action in any district court of the United States, or United States court of any Territory, to enjoin such acts or practices, and upon a proper showing, a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices to the Attorney General who may, in his discretion, institute the necessary criminal proceedings under this subchapter. Any such criminal proceeding may be brought either in the district wherein the transmittal of the prospectus or security complained of begins, or in the district wherein such prospectus or security is received."],[0,"(c) Writ of mandamus"],[0,"Upon application of the Commission, the district courts of the United States and the United States courts of any Territory shall have jurisdiction to issue writs of mandamus commanding any person to comply with the provisions of this subchapter or any order of the Commission made in pursuance thereof."],[0,"(d) Money penalties in civil actions"],[0,"(1) Authority of Commission"],[1,"Whenever it shall appear to the Commission that any person has violated any provision of this subchapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 77h–1 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation."],[0,"(2) Amount of penalty"],[0,"(A) First tier"],[2,"The amount of the penalty shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (i) $5,000 for a natural person or $50,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation."],[0,"(B) Second tier"],[2,"Notwithstanding subparagraph (A), the amount of penalty for each such violation shall not exceed the greater of (i) $50,000 for a natural person or $250,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[0,"(C) Third tier"],[2,"Notwithstanding subparagraphs (A) and (B), the amount of penalty for each such violation shall not exceed the greater of (i) $100,000 for a natural person or $500,000 for any other person, or (ii) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"],[3,"(I) the violation described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement; and"],[3,"(II) such violation directly or indirectly resulted in substantial losses or created a significant risk of substantial losses to other persons."],[0,"(3) Procedures for collection"],[0,"(A) Payment of penalty to Treasury"],[2,"A penalty imposed under this section shall be payable into the Treasury of the United States, except as otherwise provided in section 7246 of this title and section 78u–6 of this title."],[0,"(B) Collection of penalties"],[2,"If a person upon whom such a penalty is imposed shall fail to pay such penalty within the time prescribed in the court's order, the Commission may refer the matter to the Attorney General who shall recover such penalty by action in the appropriate United States district court."],[0,"(C) Remedy not exclusive"],[2,"The actions authorized by this subsection may be brought in addition to any other action that the Commission or the Attorney General is entitled to bring."],[0,"(D) Jurisdiction and venue"],[2,"For purposes of section 77v of this title, actions under this section shall be actions to enforce a liability or a duty created by this subchapter."],[0,"(4) Special provisions relating to a violation of a cease-and-desist order"],[1,"In an action to enforce a cease-and-desist order entered by the Commission pursuant to section 77h–1 of this title, each separate violation of such order shall be a separate offense, except that in the case of a violation through a continuing failure to comply with such an order, each day of the failure to comply with the order shall be deemed a separate offense."],[0,"(e) Authority of court to prohibit persons from serving as officers and directors"],[0,"In any proceeding under subsection (b), the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 77q(a)(1) of this title from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(f) Prohibition of attorneys' fees paid from Commission disgorgement funds"],[0,"Except as otherwise ordered by the court upon motion by the Commission, or, in the case of an administrative action, as otherwise ordered by the Commission, funds disgorged as the result of an action brought by the Commission in Federal court, or as a result of any Commission administrative action, shall not be distributed as payment for attorneys' fees or expenses incurred by private parties seeking distribution of the disgorged funds."],[0,"(g) Authority of a court to prohibit persons from participating in an offering of penny stock"],[0,"(1) In general"],[1,"In any proceeding under subsection (a) against any person participating in, or, at the time of the alleged misconduct, who was participating in, an offering of penny stock, the court may prohibit that person from participating in an offering of penny stock, conditionally or unconditionally, and permanently or for such period of time as the court shall determine."],[0,"(2) Definition"],[1,"For purposes of this subsection, the term \"person participating in an offering of penny stock\" includes any person engaging in activities with a broker, dealer, or issuer for purposes of issuing, trading, or inducing or attempting to induce the purchase or sale of, any penny stock. The Commission may, by rule or regulation, define such term to include other activities, and may, by rule, regulation, or order, exempt any person or class of persons, in whole or in part, conditionally or unconditionally, from inclusion in such term."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77t?type=usc&year=mostrecent&link-type=html"},"head":"§77t. Injunctions and prosecution of offenses","tname":"Commerce and Trade","by":{"0":"18, 28, 4, 5, 19, 35, 33, 10, 5, 16, 17, 10","1":"2, 7, 6","2":"19, 20, 11, 12, 13, 12, 12"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","stext":{"head":"§78a. Short title","paras":[[0,"This chapter may be cited as the \"Securities Exchange Act of 1934.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78a. Short title","tname":"Commerce and Trade","by":{"0":"3","1":"2","2":"12, 13, 14"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"head":"§78j. Manipulative and deceptive devices","tname":"Commerce and Trade","by":{"0":"9","1":"3"}},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","subs":["(j)"],"by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","subs":["(b)(4)"],"by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78t-1","url":"https://www.law.cornell.edu/uscode/text/15/78t-1","subs":["(b)(2)"],"stext":{"head":"§78t–1. Liability to contemporaneous traders for insider trading","paras":[[0,"(a) Private rights of action based on contemporaneous trading"],[0,"Any person who violates any provision of this chapter or the rules or regulations thereunder by purchasing or selling a security while in possession of material, nonpublic information shall be liable in an action in any court of competent jurisdiction to any person who, contemporaneously with the purchase or sale of securities that is the subject of such violation, has purchased (where such violation is based on a sale of securities) or sold (where such violation is based on a purchase of securities) securities of the same class."],[0,"(b) Limitations on liability"],[0,"(1) Contemporaneous trading actions limited to profit gained or loss avoided"],[1,"The total amount of damages imposed under subsection (a) shall not exceed the profit gained or loss avoided in the transaction or transactions that are the subject of the violation."],[0,"(2) Offsetting disgorgements against liability"],[1,"The total amount of damages imposed against any person under subsection (a) shall be diminished by the amounts, if any, that such person may be required to disgorge, pursuant to a court order obtained at the instance of the Commission, in a proceeding brought under section 78u(d) of this title relating to the same transaction or transactions."],[0,"(3) Controlling person liability"],[1,"No person shall be liable under this section solely by reason of employing another person who is liable under this section, but the liability of a controlling person under this section shall be subject to section 78t(a) of this title."],[0,"(4) Statute of limitations"],[1,"No action may be brought under this section more than 5 years after the date of the last transaction that is the subject of the violation."],[0,"(c) Joint and several liability for communicating"],[0,"Any person who violates any provision of this chapter or the rules or regulations thereunder by communicating material, nonpublic information shall be jointly and severally liable under subsection (a) with, and to the same extent as, any person or persons liable under subsection (a) to whom the communication was directed."],[0,"(d) Authority not to restrict other express or implied rights of action"],[0,"Nothing in this section shall be construed to limit or condition the right of any person to bring an action to enforce a requirement of this chapter or the availability of any cause of action implied from a provision of this chapter."],[0,"(e) Provisions not to affect public prosecutions"],[0,"This section shall not be construed to bar or limit in any manner any action by the Commission or the Attorney General under any other provision of this chapter, nor shall it bar or limit in any manner any action to recover penalties, or to seek any other order regarding penalties."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78t-1?type=usc&year=mostrecent&link-type=html"},"head":"§78t–1. Liability to contemporaneous traders for insider trading","tname":"Commerce and Trade","by":{"0":"37, 39","2":"18"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)","(d)(1)","(d)(3)(B)","(d)(3)(B)(ii)","(d)(4)","(d)(5)","(d)(3)(C)(iii)","(e)"],"stext":{"head":"§78u. Investigations and actions","paras":[[0,"(a) Authority and discretion of Commission to investigate violations"],[0,"(1) The Commission may, in its discretion, make such investigations as it deems necessary to determine whether any person has violated, is violating, or is about to violate any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated, or, as to any act or practice, or omission to act, while associated with a member, formerly associated with a member, the rules of a registered clearing agency in which such person is a participant, or, as to any act or practice, or omission to act, while a participant, was a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm, a person associated with such a firm, or, as to any act, practice, or omission to act, while associated with such firm, a person formerly associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the Commission shall determine, as to all the facts and circumstances concerning the matter to be investigated. The Commission is authorized in its discretion, to publish information concerning any such violations, and to investigate any facts, conditions, practices, or matters which it may deem necessary or proper to aid in the enforcement of such provisions, in the prescribing of rules and regulations under this chapter, or in securing information to serve as a basis for recommending further legislation concerning the matters to which this chapter relates."],[0,"(2) On request from a foreign securities authority, the Commission may provide assistance in accordance with this paragraph if the requesting authority states that the requesting authority is conducting an investigation which it deems necessary to determine whether any person has violated, is violating, or is about to violate any laws or rules relating to securities matters that the requesting authority administers or enforces. The Commission may, in its discretion, conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance. Such assistance may be provided without regard to whether the facts stated in the request would also constitute a violation of the laws of the United States. In deciding whether to provide such assistance, the Commission shall consider whether (A) the requesting authority has agreed to provide reciprocal assistance in securities matters to the Commission; and (B) compliance with the request would prejudice the public interest of the United States."],[0,"(b) Attendance of witnesses; production of records"],[0,"For the purpose of any such investigation, or any other proceeding under this chapter, any member of the Commission or any officer designated by it is empowered to administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the Commission deems relevant or material to the inquiry. Such attendance of witnesses and the production of any such records may be required from any place in the United States or any State at any designated place of hearing."],[0,"(c) Judicial enforcement of investigative power of Commission; refusal to obey subpena; criminal sanctions"],[0,"In case of contumacy by, or refusal to obey a subpena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. And such court may issue an order requiring such person to appear before the Commission or member or officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by such court as a contempt thereof. All process in any such case may be served in the judicial district whereof such person is an inhabitant or wherever he may be found. Any person who shall, without just cause, fail or refuse to attend and testify or to answer any lawful inquiry or to produce books, papers, correspondence, memoranda, and other records, if in his power so to do, in obedience to the subpena of the Commission, shall be guilty of a misdemeanor and, upon conviction, shall be subject to a fine of not more than $1,000 or to imprisonment for a term of not more than one year, or both."],[0,"(d) Injunction proceedings; authority of court to prohibit persons from serving as officers and directors; money penalties in civil actions; disgorgement"],[0,"(1) Whenever it shall appear to the Commission that any person is engaged or is about to engage in acts or practices constituting a violation of any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated with a member, the rules of a registered clearing agency in which such person is a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm or a person associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, it may in its discretion bring an action in the proper district court of the United States, the United States District Court for the District of Columbia, or the United States courts of any territory or other place subject to the jurisdiction of the United States, to enjoin such acts or practices, and upon a proper showing a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices as may constitute a violation of any provision of this chapter or the rules or regulations thereunder to the Attorney General, who may, in his discretion, institute the necessary criminal proceedings under this chapter."],[0,"(2) Authority of Court To Prohibit Persons From Serving as Officers and Directors.—In any proceeding under paragraph (1) of this subsection, the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 78j(b) of this title or the rules or regulations thereunder from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(3) Civil money penalties and authority to seek disgorgement.—"],[1,"(A) Authority of commission.—Whenever it shall appear to the Commission that any person has violated any provision of this chapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 78u–3 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to—"],[2,"(i) impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation; and"],[2,"(ii) require disgorgement under paragraph (7) of any unjust enrichment by the person who received such unjust enrichment as a result of such violation."],[1,"(B) Amount of penalty.—"],[2,"(i) First tier.—The amount of a civil penalty imposed under subparagraph (A)(i) shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (I) $5,000 for a natural person or $50,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation."],[2,"(ii) Second tier.—Notwithstanding clause (i), the amount of a civil penalty imposed under subparagraph (A)(i) for each such violation shall not exceed the greater of (I) $50,000 for a natural person or $250,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in subparagraph (A) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[2,"(iii) Third tier.—Notwithstanding clauses (i) and (ii), the amount of a civil penalty imposed under subparagraph (A)(i) for each violation described in that subparagraph shall not exceed the greater of (I) $100,000 for a natural person or $500,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§78u. Investigations and actions","tname":"Commerce and Trade","by":{"0":"18, 28, 5, 35, 40, 19, 33, 5, 10, 42, 37, 39, 5, 19, 30","1":"2, 7, 9","2":"13, 1, 2, 6, 14, 17, 20, 21"}},{"t":"usc","label":"15 U.S.C. § 78u-6","url":"https://www.law.cornell.edu/uscode/text/15/78u-6","subs":["(a)(4)(A)","(g)(3)(A)(i)","(g)(3)(A)(ii)"],"stext":{"head":"§78u–6. Securities whistleblower incentives and protection","paras":[[0,"(a) Definitions"],[0,"In this section the following definitions shall apply:"],[0,"(1) Covered judicial or administrative action"],[1,"The term \"covered judicial or administrative action\" means any judicial or administrative action brought by the Commission under the securities laws that results in monetary sanctions exceeding $1,000,000."],[0,"(2) Fund"],[1,"The term \"Fund\" means the Securities and Exchange Commission Investor Protection Fund."],[0,"(3) Original information"],[1,"The term \"original information\" means information that—"],[2,"(A) is derived from the independent knowledge or analysis of a whistleblower;"],[2,"(B) is not known to the Commission from any other source, unless the whistleblower is the original source of the information; and"],[2,"(C) is not exclusively derived from an allegation made in a judicial or administrative hearing, in a governmental report, hearing, audit, or investigation, or from the news media, unless the whistleblower is a source of the information."],[0,"(4) Monetary sanctions"],[1,"The term \"monetary sanctions\", when used with respect to any judicial or administrative action, means—"],[2,"(A) any monies, including penalties, disgorgement, and interest, ordered to be paid; and"],[2,"(B) any monies deposited into a disgorgement fund or other fund pursuant to section 308(b) of the Sarbanes-Oxley Act of 2002 (15 U.S.C. 7246(b)), as a result of such action or any settlement of such action."],[0,"(5) Related action"],[1,"The term \"related action\", when used with respect to any judicial or administrative action brought by the Commission under the securities laws, means any judicial or administrative action brought by an entity described in subclauses (I) through (IV) of subsection (h)(2)(D)(i) that is based upon the original information provided by a whistleblower pursuant to subsection (a) that led to the successful enforcement of the Commission action."],[0,"(6) Whistleblower"],[1,"The term \"whistleblower\" means any individual who provides, or 2 or more individuals acting jointly who provide, information relating to a violation of the securities laws to the Commission, in a manner established, by rule or regulation, by the Commission."],[0,"(b) Awards"],[0,"(1) In general"],[1,"In any covered judicial or administrative action, or related action, the Commission, under regulations prescribed by the Commission and subject to subsection (c), shall pay an award or awards to 1 or more whistleblowers who voluntarily provided original information to the Commission that led to the successful enforcement of the covered judicial or administrative action, or related action, in an aggregate amount equal to—"],[2,"(A) not less than 10 percent, in total, of what has been collected of the monetary sanctions imposed in the action or related actions; and"],[2,"(B) not more than 30 percent, in total, of what has been collected of the monetary sanctions imposed in the action or related actions."],[0,"(2) Payment of awards"],[1,"Any amount paid under paragraph (1) shall be paid from the Fund."],[0,"(c) Determination of amount of award; denial of award"],[0,"(1) Determination of amount of award"],[0,"(A) Discretion"],[2,"The determination of the amount of an award made under subsection (b) shall be in the discretion of the Commission."],[0,"(B) Criteria"],[2,"In determining the amount of an award made under subsection (b), the Commission—"],[3,"(i) shall take into consideration—"],[4,"(I) the significance of the information provided by the whistleblower to the success of the covered judicial or administrative action;"],[4,"(II) the degree of assistance provided by the whistleblower and any legal representative of the whistleblower in a covered judicial or administrative action;"],[4,"(III) the programmatic interest of the Commission in deterring violations of the securities laws by making awards to whistleblowers who provide information that lead to the successful enforcement of such laws; and"],[4,"(IV) such additional relevant factors as the Commission may establish by rule or regulation; and"],[3,"(ii) shall not take into consideration the balance of the Fund."],[0,"(2) Denial of award"],[1,"No award under subsection (b) shall be made—"],[2,"(A) to any whistleblower who is, or was at the time the whistleblower acquired the original information submitted to the Commission, a member, officer, or employee of—"],[3,"(i) an appropriate regulatory agency;"],[3,"(ii) the Department of Justice;"],[3,"(iii) a self-regulatory organization;"],[3,"(iv) the Public Company Accounting Oversight Board; or"],[3,"(v) a law enforcement organization;"],[2,"(B) to any whistleblower who is convicted of a criminal violation related to the judicial or administrative action for which the whistleblower otherwise could receive an award under this section;"],[2,"(C) to any whistleblower who gains the information through the performance of an audit of financial statements required under the securities laws and for whom such submission would be contrary to the requirements of section 78j–1 of this title; or"],[2,"(D) to any whistleblower who fails to submit information to the Commission in such form as the Commission may, by rule, require."],[0,"(d) Representation"],[0,"(1) Permitted representation"],[1,"Any whistleblower who makes a claim for an award under subsection (b) may be represented by counsel."],[0,"(2) Required representation"],[0,"(A) In general"],[2,"Any whistleblower who anonymously makes a claim for an award under subsection (b) shall be represented by counsel if the whistleblower anonymously submits the information upon which the claim is based."],[0,"(B) Disclosure of identity"],[2,"Prior to the payment of an award, a whistleblower shall disclose the identity of the whistleblower and provide such other information as the Commission may require, directly or through counsel for the whistleblower."],[0,"(e) No contract necessary"],[0,"No contract with the Commission is necessary for any whistleblower to receive an award under subsection (b), unless otherwise required by the Commission by rule or regulation."],[0,"(f) Appeals"],[0,"Any determination made under this section, including whether, to whom, or in what amount to make awards, shall be in the discretion of the Commission. Any such determination, except the determination of the amount of an award if the award was made in accordance with subsection (b), may be appealed to the appropriate court of appeals of the United States not more than 30 days after the determination is issued by the Commission. The court shall review the determination made by the Commission in accordance with section 706 of title 5."],[0,"(g) Investor Protection Fund"],[0,"(1) Fund established"],[1,"There is established in the Treasury of the United States a fund to be known as the \"Securities and Exchange Commission Investor Protection Fund\"."],[0,"(2) Use of Fund"],[1,"The Fund shall be available to the Commission, without further appropriation or fiscal year limitation, for—"],[2,"(A) paying awards to whistleblowers as provided in subsection (b); and"],[2,"(B) funding the activities of the Inspector General of the Commission under section 78d(i) of this title."],[0,"(3) Deposits and credits"],[0,"(A) In general"],[2,"There shall be deposited into or credited to the Fund an amount equal to—"],[3,"(i) any monetary sanction collected by the Commission in any judicial or administrative action brought by the Commission under the securities laws that is not added to a disgorgement fund or other fund under section 308 of the Sarbanes-Oxley Act of 2002 (15 U.S.C. 7246) or otherwise distributed to victims of a violation of the securities laws, or the rules and regulations thereunder, underlying such action, unless the balance of the Fund at the time the monetary sanction is collected exceeds $300,000,000;"],[3,"(ii) any monetary sanction added to a disgorgement fund or other fund under section 308 of the Sarbanes-Oxley Act of 2002 (15 U.S.C. 7246) that is not distributed to the victims for whom the Fund was established, unless the balance of the disgorgement fund at the time the determination is made not to distribute the monetary sanction to such victims exceeds $200,000,000; and"],[3,"(iii) all income from investments made under paragraph (4)."],[0,"(B) Additional amounts"],[2,"If the amounts deposited into or credited to the Fund under subparagraph (A) are not sufficient to satisfy an award made under subsection (b), there shall be deposited into or credited to the Fund an amount equal to the unsatisfied portion of the award from any monetary sanction collected by the Commission in the covered judicial or administrative action on which the award is based."],[0,"(4) Investments"],[0,"(A) Amounts in Fund may be invested"],[2,"The Commission may request the Secretary of the Treasury to invest the portion of the Fund that is not, in the discretion of the Commission, required to meet the current needs of the Fund."],[0,"(B) Eligible investments"],[2,"Investments shall be made by the Secretary of the Treasury in obligations of the United States or obligations that are guaranteed as to principal and interest by the United States, with maturities suitable to the needs of the Fund as determined by the Commission on the record."],[0,"(C) Interest and proceeds credited"],[2,"The interest on, and the proceeds from the sale or redemption of, any obligations held in the Fund shall be credited to the Fund."],[0,"(5) Reports to Congress"],[1,"Not later than October 30 of each fiscal year beginning after July 21, 2010, the Commission shall submit to the Committee on Banking, Housing, and Urban Affairs of the Senate, and the Committee on Financial Services of the House of Representatives a report on—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-6?type=usc&year=mostrecent&link-type=html"},"head":"§78u–6. Securities whistleblower incentives and protection","tname":"Commerce and Trade","by":{"0":"36, 36, 36","2":"19"}},{"t":"usc","label":"8 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/8/1153","subs":["(b)(5)(A)"],"by":{"0":"7"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(19)","(a)(19)(B)(iii)"],"stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"head":"§523. Exceptions to discharge","tname":"Bankruptcy","by":{"0":"36","1":"20"}},{"t":"usc","label":"15 U.S.C. § 7246","url":"https://www.law.cornell.edu/uscode/text/15/7246","subs":["(a)"],"stext":{"head":"§7246. Fair funds for investors","paras":[[0,"(a) Civil penalties to be used for the relief of victims"],[0,"If, in any judicial or administrative action brought by the Commission under the securities laws, the Commission obtains a civil penalty against any person for a violation of such laws, or such person agrees, in settlement of any such action, to such civil penalty, the amount of such civil penalty shall, on the motion or at the direction of the Commission, be added to and become part of a disgorgement fund or other fund established for the benefit of the victims of such violation."],[0,"(b) Acceptance of additional donations"],[0,"The Commission is authorized to accept, hold, administer, and utilize gifts, bequests and devises of property, both real and personal, to the United States for a disgorgement fund or other fund described in subsection (a). Such gifts, bequests, and devises of money and proceeds from sales of other property received as gifts, bequests, or devises shall be deposited in such fund and shall be available for allocation in accordance with subsection (a)."],[0,"(c) Study required"],[0,"(1) Subject of study"],[1,"The Commission shall review and analyze—"],[2,"(A) enforcement actions by the Commission over the five years preceding July 30, 2002, that have included proceedings to obtain civil penalties or disgorgements to identify areas where such proceedings may be utilized to efficiently, effectively, and fairly provide restitution for injured investors; and"],[2,"(B) other methods to more efficiently, effectively, and fairly provide restitution to injured investors, including methods to improve the collection rates for civil penalties and disgorgements."],[0,"(2) Report required"],[1,"The Commission shall report its findings to the Committee on Financial Services of the House of Representatives and the Committee on Banking, Housing, and Urban Affairs of the Senate within 180 days after of 1 July 30, 2002, and shall use such findings to revise its rules and regulations as necessary. The report shall include a discussion of regulatory or legislative actions that are recommended or that may be necessary to address concerns identified in the study."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/7246?type=usc&year=mostrecent&link-type=html"},"head":"§7246. Fair funds for investors","tname":"Commerce and Trade","by":{"0":"36","2":"19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 2462","url":"https://www.law.cornell.edu/uscode/text/28/2462","stext":{"head":"§2462. Time for commencing proceedings","paras":[[0,"Except as otherwise provided by Act of Congress, an action, suit or proceeding for the enforcement of any civil fine, penalty, or forfeiture, pecuniary or otherwise, shall not be entertained unless commenced within five years from the date when the claim first accrued if, within the same period, the offender or the property is found within the United States in order that proper service may be made thereon."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2462?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2462. Time for commencing proceedings","tname":"Judiciary and Judicial Procedure","by":{"0":"11, 25","1":"32"}},{"t":"reg","label":"8 C.F.R. § 204.6","url":"https://www.ecfr.gov/current/title-8/section-204.6","subs":["(h)(1)"],"by":{"0":"7"}},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","by":{"0":"9, 39","1":"3"}},{"t":"case","label":"Ankenbrandt v. Richards","cite":"504 U.S. 689","y":1992,"id":"1991/91-367","sc":1,"sum":"Petitioner brought this suit on behalf of her daughters in the District Court, alleging federal jurisdiction based on the diversity-of-citizenship provision of 28 U. S. C. § 1332, and seeking monetary damages for alleged torts committed against the girls by their father and his female companion, the respondents here. The court granted respondents' motion to dismiss without prejudice, ruling in the alternative that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"BNSF Ry. Co. v. Loos","cite":"139 S. Ct. 893","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"1":"26","2":"20"}},{"t":"case","label":"Callaghan v. Myers","cite":"128 U.S. 617","y":1888,"id":"scdb/1888-073","sc":1,"op":2,"sum":"Although there can be no copyright in the opinions of the judges of a court, or in the work done by them in their official capacity as judges, there is no ground of public policy on which a reporter, who prepares a volume of law reports, of the usual character, can be debarred from obtaining a copyright for the volume, which will cover the mattenwhich is the result of his intellectual labor.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"40, 42"}},{"t":"case","label":"Chauffeurs, Teamsters & Helpers v. Terry","cite":"494 U.S. 558","y":1990,"id":"1989/88-1719","sc":1,"op":1,"sum":"The judgment is affirmed. 863 F. 2d 334, affirmed. JUSTICE MARSHALL delivered the opinion of the Court with respect to Parts 1, 11, III-B, and IV, concluding that the Seventh Amendment entitles respondents to a jury trial. Pp. 563-564, 570-574.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"9","2":"10"}},{"t":"case","label":"Dickson v. Patterson","cite":"160 U.S. 584","y":1896,"id":"scdb/1895-096","sc":1,"sum":"In May, 1888, 3?., having an opportunity to purchase ten acres oí land near Omaha, at a cost of $3600, payable $1250 in cash, the rest on credit, wrote to D. that he could buy the tract for $4800, payable $2500 in cash, the rest on credit, and asked him to join-in the purchase. D. assented, sent his $1250 to P., and joined in a mortgage for the balance of the purchase money. In October, 1885, P. wrote to D. that he …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"31","2":"9"}},{"t":"case","label":"Elizabeth v. Pavement Co.","cite":"97 U.S. 126","y":1878,"id":"scdb/1877-248","sc":1,"op":5,"by":{"1":"40, 42"}},{"t":"case","label":"Feltner v. Columbia Pictures Television, Inc.","cite":"523 U.S. 340","y":1998,"id":"1997/96-1768","sc":1,"op":3,"sum":"The Court held that, despite section 504(c) of the Copyright Act's silence, the Seventh Amendment provides the right to a jury trial, which includes a right to a jury determination of the amount of statutory damages.","sumSrc":"Oyez","by":{"1":"8","2":"10"}},{"t":"case","label":"General Dynamics Land Systems, Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Jackson v. Smith","cite":"254 U.S. 586","y":1921,"id":"scdb/1920-206","sc":1,"op":1,"sum":"Persons who knowingly join with a receiver in purchasing real estate at a sale made by the trustee of a deed of trust mortgage' securing a debt due the receivership, are jointly and severally liable to the receivership for all profits realized from the purchase.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32","2":"8"}},{"t":"case","label":"Kansas v. Nebraska","cite":"574 U.S. 445","y":2015,"id":"2014/126-orig","sc":1,"op":3,"ar":3,"sum":"The Court ruled that Nebraska violated a compact apportioning the water resources of the Republican River among Kansas, Nebraska and Colorado.","sumSrc":"Oyez","by":{"1":"8, 34, 35","2":"10, 11"}},{"t":"case","label":"Lexmark Int’l, Inc., v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Litton Indus., Inc. v. Lehman Bros. Kuhn Loeb Inc.","cite":"734 F. Supp. 1071","y":1990,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./734/1071/","by":{"1":"41"}},{"t":"case","label":"Manhattan Properties, Inc. v. Irving Trust Co.","cite":"291 U.S. 320","y":1934,"id":"scdb/1933-048","sc":1,"sum":"1. The claim of a landlord for future rents based on a covenant to p'ay rent in a lease terminated by reintry on the bankruptcy of the tenant, is not a provable debt under § 63 (a) of the Bankruptcy Act. P. 332. So held in view of the great weight of judicial authority construing that section and similar provisions of earlier Acts, and in view of the legislative history of the subject.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23","2":"17"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Miles v. Apex Marine Corp.","cite":"489 U.S. 19","y":1990,"id":"1990/89-1158","sc":1,"sum":"Petitioner Miles, the mother and administratrix of the estate of a seaman killed by a fellow crew member aboard the vessel of respondents (collectively Apex) docked in an American port, sued Apex in District Court, alleging negligence under the Jones Act for failure to prevent the assault, and breach of the warranty of seaworthiness under general maritime law for hiring a crew member unfit to serve. After the court …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"op":2,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"National Lead Co. v. United States","cite":"252 U.S. 140","y":1920,"id":"scdb/1919-153","sc":1,"sum":"Section 22 of the Act of August 27,1894, c. 349, 28 Stilt. 509, provides: “That where imported materials on which duties have been paid are used in the manufacture of articles manufactured or produced in the United States, there shall be allowed on the exportation of such articles a drawback equal in amount to the duties paid on the materials used, less one per centum of such duties,” to be paid under such …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"op":2,"sum":"The Court held that the doctrine of laches could not be used to prevent a copyright suit that seeks relief for damages that occurred within the three-year window allowed by the Copyright Act.","sumSrc":"Oyez","by":{"1":"8","2":"10, 11"}},{"t":"case","label":"Riggs v. Palmer","cite":"22 N.E. 188","y":1889,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./22/188/","by":{"1":"10"}},{"t":"case","label":"SCA Hygiene Products Aktiebolag v. First Quality Baby Products, LLC","cite":"137 S. Ct. 954","y":2017,"id":"2016/15-927","sc":1,"op":1,"sum":"The Court determined that an unreasonable delay in litigation cannot bar claims for patent infringement that are brought within the six-year statutory period of limitations.","sumSrc":"Oyez","by":{"1":"9"}},{"t":"case","label":"SEC v. Blatt","cite":"583 F.2d 1325","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/583/1325/","op":1,"ar":1,"by":{"1":"13","2":"15, 16"}},{"t":"case","label":"SEC v. Blavin","cite":"760 F.2d 706","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/760/706/","by":{"1":"38"}},{"t":"case","label":"SEC v. Calvo","cite":"378 F.3d 1211","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/378/1211/","by":{"1":"12","2":"16"}},{"t":"case","label":"SEC v. Cavanagh","cite":"445 F.3d 105","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/445/105/","op":1,"by":{"1":"31"}},{"t":"case","label":"SEC v. First City Financial Corp.","cite":"890 F.2d 1215","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/890/1215/","by":{"1":"12","2":"15"}},{"t":"case","label":"SEC v. Gotchey","cite":"981 F.2d 1251","y":1992,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/1251/","by":{"1":"12"}},{"t":"case","label":"SEC v. Hughes Capital Corp.","cite":"124 F.3d 449","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/124/449/","op":1,"by":{"1":"12","2":"15"}},{"t":"case","label":"SEC v. JT Wallenbrock & Assocs.","cite":"440 F.3d 1109","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/440/1109/","op":2,"sum":"Reasoning that it would be “unjust to permit the defendants to offset . . . the expenses of running the very business they created to defraud . . . investors”.","sumSrc":"opinion","by":{"1":"41"}},{"t":"case","label":"SEC v. Lipson","cite":"278 F.3d 656","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/278/656/","ar":1,"by":{"1":"12","2":"15, 16"}},{"t":"case","label":"SEC v. MacDonald","cite":"699 F.2d 47","y":1983,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/699/47/","by":{"1":"12","2":"15, 16"}},{"t":"case","label":"SEC v. Manor Nursing Centers, Inc.","cite":"458 F.2d 1082","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/458/1082/","op":2,"by":{"1":"41"}},{"t":"case","label":"SEC v. McCaskey","cite":"2002 WL 850001","y":2002,"court":"S.D.N.Y. Mar. 26","by":{"1":"41"}},{"t":"case","label":"SEC v. Patel","cite":"61 F.3d 137","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/61/137/","by":{"1":"41"}},{"t":"case","label":"SEC v. Randolph","cite":"736 F.2d 525","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/736/525/","by":{"1":"12","2":"15, 16"}},{"t":"case","label":"SEC v. Ridenour","cite":"913 F.2d 515","y":1990,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/913/515/","by":{"1":"12","2":"15"}},{"t":"case","label":"SEC v. Rosenfeld","cite":"2001 WL 118612","y":2001,"court":"S.D.N.Y. Jan. 9","by":{"1":"41"}},{"t":"case","label":"SEC v. Smyth","cite":"420 F.3d 1225","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/420/1225/","by":{"1":"41"}},{"t":"case","label":"SEC v. Team Resources Inc.","cite":"942 F.3d 272","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/942/272/","by":{"1":"42"}},{"t":"case","label":"SEC v. Thomas James Assocs., Inc.","cite":"738 F. Supp. 88","y":1990,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./738/88/","by":{"1":"41"}},{"t":"case","label":"SEC v. Washington County Utility District","cite":"676 F.2d 218","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/676/218/","op":1,"by":{"1":"13","2":"15"}},{"t":"case","label":"Simon & Schuster, Inc., v. Members of the New York State Crime Victims Board","cite":"502 U.S. 105","y":1991,"id":"1991/90-1059","sc":1,"sum":"The Court concluded that \"New York has singled out speech on a particular subject for a financial burden that it places on no other speech and no other income.\" This discrimination could only be justified if the state could show \"that its regulation is necessary to serve a compelling state interest and is narrowly drawn to achieve that end\" (Arkansas Writers' Project, Inc. v. Ragland, 481 U.S. 221, 231 (1987)).","sumSrc":"Oyez","by":{"1":"10"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"United States SEC v. Maxxon, Inc.","cite":"465 F.3d 1174","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/1174/","by":{"1":"12","2":"16"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"16, 17, 28, 44"}},{"t":"law","label":"Pub. L. No. 100-704","url":"https://www.govinfo.gov/link/statute/102/4677","by":{"1":"14, 15, 24"}},{"t":"usc","label":"15 U.S.C. § 77v","url":"https://www.law.cornell.edu/uscode/text/15/77v","subs":["(a)"],"by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 78aa","url":"https://www.law.cornell.edu/uscode/text/15/78aa","subs":["(a)"],"by":{"1":"2"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"op":2,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"2":"14, 16"}},{"t":"case","label":"Brooks v. Conston","cite":"72 A.2d 75","y":1950,"court":"Pa.","url":"https://www.courtlistener.com/c/A.2d/72/75/","by":{"2":"9"}},{"t":"case","label":"Dowagiac Mfg. Co. v. Minnesota Moline Plow Co.","cite":"235 U.S. 641","y":1915,"id":"scdb/1914-255","sc":1,"sum":"Where a patent is infringed by selling machines embodying improvements covered by the patent and the value of the machines as marketable articles is attributable in part to the patented improvements and in part to unpatented parts or features, the profits arising from the infringing sales belong to the owner of the patent in so far as they are attributable to the patented improvements, and in so far as they are due …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Falk v. Hoffman","cite":"135 N.E. 243","y":1922,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./135/243/","by":{"2":"9"}},{"t":"case","label":"Iselin v. United States","cite":"270 U.S. 245","y":1926,"id":"scdb/1925-076","sc":1,"sum":"1. Par. 3 of § 800(a) of Revenue Act of 1918, laying taxes on theater and opera tickets sold at newstands, hotels, etc., for more than the “established price” at the ticket office of the theater or opera house, held inapplicable to sale by a stockholder of box tickets, issued as an incident of his investment in an opera house company, which were not sold at the box-office and for which there was no established price.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Lang v. Giraudo","cite":"40 N.E.2d 707","y":1942,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/40/707/","by":{"2":"9"}},{"t":"case","label":"Lightfoot v. Cendant Mortg. Corp.","cite":"137 S. Ct. 553","y":2017,"id":"2016/14-1055","sc":1,"sum":"The Court determined that language in the federal charter of the Federal National Mortgage Association (Fannie Mae) that authorizes the organization to sue and be sued does not mean that federal courts have subject matter jurisdiction over any case in which Fannie Mae is a plaintiff or defendant, and the Supreme Court’s precedent in American National Red Cross v. S.G. doe not require a different result.","sumSrc":"Oyez","by":{"2":"14, 16"}},{"t":"case","label":"Meinhard v. Salmon","cite":"164 N.E. 545","y":1928,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./164/545/","by":{"2":"9"}},{"t":"case","label":"Middlesex Cty. Sewerage Auth. v. National Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Mills v. Electric Auto-Lite Co.","cite":"396 U.S. 375","y":1970,"id":"1969/64","sc":1,"sum":"Petitioners, minority shareholders of respondent Electric Auto-Lite Co., brought this action derivatively and on behalf of minority shareholders as a class to set aside a merger of Auto-Lite and the Mergenthaler Linotype Co. (which before the merger owned over half of Auto-Lite's stock). Petitioners charged that the proxy solicitation for the merger by Auto-Lite's management was materially misleading and violated § …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"op":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Pierce v. SEC","cite":"737 F. Supp. 2d 1068","y":2010,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/737/1068/","by":{"2":"21"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"SEC v. Gotchey","cite":"1992 WL 385284","y":1992,"court":"4th Cir. Dec. 28","by":{"2":"15, 16"}},{"t":"case","label":"SEC v. Rajaratnam","cite":"918 F.3d 36","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/918/36/","by":{"2":"13"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Smith v. Jackson","cite":"48 App. D.C. 565","y":1919,"url":"https://www.courtlistener.com/c/App.%20D.C./48/565/","op":1,"by":{"2":"8"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Tilghman v. Proctor","cite":"125 U.S. 136","y":1888,"id":"scdb/1887-171","sc":1,"op":3,"sum":"One having an interest in all fees and other sums to be recovered under a patent, but not shown to have'any interest, legal or equitable, in the patent itself, need not be made a party to a bill in equity for its infringement.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"6, 10"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(3)"],"by":{"2":"6"}},{"t":"usc","label":"15 U.S.C. § 78dd-1","url":"https://www.law.cornell.edu/uscode/text/15/78dd-1","by":{"2":"5, 6"}},{"t":"usc","label":"15 U.S.C. § 80b-1","url":"https://www.law.cornell.edu/uscode/text/15/80b-1","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 80b-3","url":"https://www.law.cornell.edu/uscode/text/15/80b-3","subs":["(e)","(i)"],"by":{"2":"12, 12"}},{"t":"usc","label":"15 U.S.C. § 80a-1","url":"https://www.law.cornell.edu/uscode/text/15/80a-1","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 80a-9","url":"https://www.law.cornell.edu/uscode/text/15/80a-9","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 80a-41","url":"https://www.law.cornell.edu/uscode/text/15/80a-41","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 80a-48","url":"https://www.law.cornell.edu/uscode/text/15/80a-48","by":{"2":"12"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","by":{"2":"12"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","by":{"2":"12"}},{"t":"law","label":"Pub. L. No. 107-204","url":"https://www.govinfo.gov/link/plaw/107/public/204","by":{"2":"16, 19"}},{"t":"usc","label":"15 U.S.C. § 77x","url":"https://www.law.cornell.edu/uscode/text/15/77x","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 78f","url":"https://www.law.cornell.edu/uscode/text/15/78f","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 78j-1","url":"https://www.law.cornell.edu/uscode/text/15/78j-1","subs":["(d)"],"by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 78u-1","url":"https://www.law.cornell.edu/uscode/text/15/78u-1","by":{"2":"12, 18"}},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 78u-3","url":"https://www.law.cornell.edu/uscode/text/15/78u-3","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 77aaa","url":"https://www.law.cornell.edu/uscode/text/15/77aaa","by":{"2":"12"}},{"t":"usc","label":"15 U.S.C. § 77yyy","url":"https://www.law.cornell.edu/uscode/text/15/77yyy","by":{"2":"12"}}]};